/**
 * @description Sandbox-only self-test kit for Integration Hub Lite. The org calls its own Integration Hub endpoint
 * through Named Credential IH_Self_Org; this one class plays every role of the round trip: inbound handler
 * (SELF_ECHO, SELF_REJECT, SELF_DOWN, SELF_CASE_CREATE), payload class (SELF_SEND_CLASS) and response handler.
 * Do not deploy to production.
 * @group Integration Hub
 */
public with sharing class IH_SelfTestKit implements IntegrationHub.IInboundHandler, IntegrationHub.IPayloadBuilder,
        IntegrationHub.IResponseHandler {

    /** @description Value of the source key in every payload this class builds. */
    public static final String SOURCE = 'IH_SelfTestKit';
    /** @description Prefix of the reference returned by the echo. */
    public static final String REFERENCE_PREFIX = 'SELF-';
    /** @description Status returned when the event key contains REJECT. */
    public static final Integer REJECT_STATUS = 422;
    /** @description Status returned when the event key contains DOWN. */
    public static final Integer DOWN_STATUS = 503;
    /** @description Error text of a rejected call. */
    public static final String REJECT_MESSAGE = 'Rejected on purpose by the self-org test';
    /** @description Error text of a call to a system that is down. */
    public static final String DOWN_MESSAGE = 'Unavailable on purpose by the self-org test';
    /** @description Case fields the create mode copies from the body. */
    private static final List<String> CREATE_FIELDS = new List<String>{ 'Subject', 'Origin', 'Status', 'Priority' };

    /**
     * @description Inbound handler: an event key containing REJECT fails with 422 (not retryable), one containing
     * DOWN fails with 503 (retryable); one containing CREATE creates a Case from the body; anything else succeeds and
     * echoes the call. The echo carries a 'reference'
     * key, the key IntegrationHubCallout reads as External Reference Id, and links the inbound transaction to the
     * record the sender sent ("recordId" in the body), so it shows on that record's page too.
     * @param ctx the call
     * @return the result
     */
    public IntegrationHub.InboundResult handle(IntegrationHub.InboundContext ctx) {
        String key = ctx == null || ctx.eventKey == null ? '' : ctx.eventKey;
        if (key.containsIgnoreCase('REJECT')) {
            return IntegrationHub.inboundFailure(REJECT_STATUS, REJECT_MESSAGE);
        }
        if (key.containsIgnoreCase('DOWN')) {
            return IntegrationHub.inboundFailure(DOWN_STATUS, DOWN_MESSAGE);
        }
        if (key.containsIgnoreCase('CREATE')) {
            return createCase(ctx.data);
        }
        return IntegrationHub.inboundSuccess(sentRecordId(ctx), new Map<String, Object>{
            'received' => ctx == null ? null : ctx.data,
            'eventKey' => key,
            'inboundTransactionId' => ctx == null ? null : ctx.transactionId,
            'reference' => REFERENCE_PREFIX + shortUnique()
        });
    }

    /**
     * @description Create mode: a Case from Subject, Origin, Status and Priority in the body (flat or under
     * "fields", the shape Selected Fields sends). The transaction is linked to the new Case.
     * @param data the parsed body
     * @return success with the new Case, 400 without a Subject, or 422 when the org refuses the Case
     */
    @TestVisible
    private static IntegrationHub.InboundResult createCase(Map<String, Object> data) {
        Object nested = data == null ? null : data.get('fields');
        Map<String, Object> fields = nested instanceof Map<String, Object> ? (Map<String, Object>) nested : data;
        if (fields == null || fields.get('Subject') == null) {
            return IntegrationHub.inboundFailure(400, 'Subject is required.');
        }
        Case c = new Case();
        for (String name : CREATE_FIELDS) {
            if (fields.get(name) != null) {
                c.put(name, String.valueOf(fields.get(name)));
            }
        }
        try {
            new Elevated().create(c);
            return IntegrationHub.inboundSuccess(c.Id, new Map<String, Object>{ 'caseId' => c.Id });
        } catch (DmlException e) {
            return IntegrationHub.inboundFailure(422, 'Case not created: ' + e.getDmlMessage(0));
        }
    }

    /**
     * @description The record the sender sent ("recordId" in the body). Null when the body has no valid record Id.
     * @param ctx the call
     * @return the record Id, or null
     */
    @TestVisible
    private static Id sentRecordId(IntegrationHub.InboundContext ctx) {
        Object value = ctx == null || ctx.data == null ? null : ctx.data.get('recordId');
        if (!(value instanceof String)) {
            return null;
        }
        try {
            return Id.valueOf((String) value);
        } catch (StringException e) {
            return null;
        }
    }

    /**
     * @description Payload class: one body per Case, from a single query. Ids that are not Cases, or Cases that no
     * longer exist, get no body.
     * @param req the event and the record Ids
     * @return the body per record Id: {source, caseId, caseNumber, subject}
     */
    public Map<Id, Object> build(IntegrationHub.PayloadRequest req) {
        Map<Id, Object> bodies = new Map<Id, Object>();
        if (req == null || req.recordIds == null || req.recordIds.isEmpty()) {
            return bodies;
        }
        for (Case c : new Elevated().casesById(new Set<Id>(req.recordIds))) {
            bodies.put(c.Id, new Map<String, Object>{
                'source' => SOURCE, 'caseId' => c.Id, 'caseNumber' => c.CaseNumber, 'subject' => c.Subject });
        }
        return bodies;
    }

    /**
     * @description Response handler: writes the reply or callback to the debug log only. No DML, no field changes.
     * @param ctx the reply or callback
     */
    @SuppressWarnings('PMD.AvoidDebugStatements')
    public void handle(IntegrationHub.ResponseContext ctx) {
        if (ctx == null) {
            return;
        }
        System.debug(LoggingLevel.INFO, SOURCE + ' response: transaction ' + ctx.transactionId + ', callback '
            + ctx.isCallback + ', HTTP ' + ctx.httpStatus + ', body ' + IntegrationHub.clip(ctx.body, 1000));
    }

    /**
     * @description A short random text that makes each reference unique.
     * @return 8 hexadecimal characters
     */
    @TestVisible
    private static String shortUnique() {
        return EncodingUtil.convertToHex(Crypto.generateAesKey(128)).left(8).toUpperCase();
    }

    /**
     * @description Reads and creates Cases in system mode, so neither depends on the user's access.
     */
    private without sharing class Elevated {

        List<Case> casesById(Set<Id> caseIds) {
            return [SELECT Id, CaseNumber, Subject FROM Case WHERE Id IN :caseIds WITH SYSTEM_MODE LIMIT 2000];
        }

        void create(Case c) {
            insert as system c;
        }
    }
}
